Inherited evidence: [{"book":"PZO1110","reason":"Complete UUID-linked or explicitly inspected named rule body; cited publication minimum only.","evidence":"<p>The subject becomes paralyzed and freezes in place. It is aware and breathes normally but cannot take any actions, even speech. Each round on its turn, the subject may attempt a new saving throw to end the effect. This is a full-round action that does not provoke attacks of opportunity. A winged creature who is paralyzed cannot flap its wings and falls. A swimmer can't swim and may drown.</p>","evidenceSha256":"b85c2a8c80f71a024d68393f82ed883b533e0668feaf544b0f1cb58ba8c4e517","sourceLocation":"https://gitlab.com/foundryvtt_pathfinder1e/foundryvtt-pathfinder1/-/blob/418761d2e16a6037c0156bb4a241f7cea5a2986d/packs/spells/hold-person.78kwl5t99j9e8tzh.yaml","sourceDescriptionSha256":"b85c2a8c80f71a024d68393f82ed883b533e0668feaf544b0f1cb58ba8c4e517","sourceFileSha256":"be33f4b1640344d49ec95678da054b382f20c99b7c29a22517904ac5e064c810","comparisonEvidence":[],"role":"complete-source-body"},{"book":"PZO1110","reason":"Explicit core action, condition, damage, skill, save or component rule. PCGen declaration is a publication anchor, not a comparison to this particular clause.","evidence":"saving throw","evidenceSha256":"3fb47c4b5c8d69f9bef7d6b22d4c84025f22a08fde122183a9ca71a33939be5a","sourceLocation":"https://gitlab.com/foundryvtt_pathfinder1e/foundryvtt-pathfinder1/-/blob/418761d2e16a6037c0156bb4a241f7cea5a2986d/packs/spells/halt-undead.f98kluovmjf6w7d5.yaml","sourceDescriptionSha256":"f7eba28db467aa6742cfa5f10fae7a682a76651a2fed7ab2db1ff6479da37f54","sourceFileSha256":"6ced400f6571af5a5b7e4d9dde844a14530d5f1681b979101ac8200a1aa82889","comparisonEvidence":[{"source":"comparison/core_rulebook.pcc","line":14,"text":"SOURCELONG:Core Rulebook","textSha256":"8bde3fab596f83579c58382af615faef715a76cc261b532ab271caee71eb1fc5","fileSha256":"8638a1197e2a541695f3005feb1a6eb67569220a5b0f151bc37819d3121feb06","role":"publication-an