const blindsense = item.system.level >= 15 ? 10 : 0;

if(state) {
  await item.setItemDictionaryFlag("dvRange", actor.system.traits.senses.dv);
  await item.setItemDictionaryFlag("bseRange", actor.system.traits.senses.bse);

  await actor.update({
    "system.traits.senses.dv": darkvisionRange,
