} else {
  await actor.update({
    "system.traits.senses.dv": item.getItemDictionaryFlag("dvRange") ?? 0,
    "system.traits.senses.bse": item.getItemDictionaryFlag("bseRange") ?? 0,
  });

  await item.removeItemDictionaryFlag("dvRange");
  await item.removeItemDictionaryFlag("bseRange");
}"

